9052660ada8","level":"PPSC","subjects":[{"name":"General Knowledge","topics":["Pakistan History","Geography","Current Affairs","Islamic Studies","World GK","Science & Tech"]},{"name":"English","topics":["Grammar","Vocabulary","Sentence Correction","Comprehension","Synonyms","Antonyms"]},{"name":"Pakistan Studies","topics":["Pakistan History","Constitution","Geography","Economy","Foreign Policy","Current Affairs"]},{"name":"Mathematics","topics":["Basic Arithmetic","Algebra","Geometry","Percentage","Ratio","Profit & Loss"]}]},{"system_id":"3f529ffc-4cdb-4df3-a618-2077408c56b7","level":"PST & SST Tests","subjects":[{"name":"Education & Pedagogy","topics":["Teaching Methods","Child Psychology","Classroom Management","Curriculum","Assessment","Special Education"]},{"name":"General Knowledge","topics":["Pakistan Studies","Islamic Studies","Current Affairs","Science GK","World Affairs","Sports"]},{"name":"English","topics":["Grammar","Vocabulary","Comprehension","Sentence Correction","Teaching English","Writing Skills"]},{"name":"Subject Knowledge","topics":["Mathematics","Biology","Chemistry","Physics","Computer Science","Social Studies"]}]},{"system_id":"5f97e59a-b578-4369-8e14-5d8b69493419","level":"Pakistan Army Test","subjects":[{"name":"Intelligence & IQ","topics":["Verbal Intelligence","Non-Verbal Intelligence","Analytical Reasoning","Logical Reasoning","Pattern Recognition","Mathematical Reasoning","Spatial Reasoning","Memory Test"]},{"name":"General Knowledge","topics":["Pakistan Studies","Pakistan Army History","Current Affairs","Islamic Studies","World Affairs","Geography","Science & Tech","Sports"]},{"name":"Mathematics","topics":["Arithmetic","Algebra","Geometry","Percentage","Ratio & Proportion","Time & Work","Speed & Distance","Statistics"]},{"name":"English","topics":["Grammar","Vocabulary","Comprehension","Sentence Correction","Synonyms & Antonyms","Fill in the Blanks"]}]},{"system_id":"baaea996-b2e0-4f23-87fd-d7ef3bce6301","level":"Punjab University Entry Test","subjects":[{"name":"English","topics":["Grammar","Vocabulary","Comprehension","Sentence Correction","Synonyms","Antonyms"]},{"name":"General Knowledge","topics":["Pakistan Affairs","Current Affairs","Islamic Studies","World GK","Science","History"]},{"name":"Science & Mathematics","topics":["Biology","Chemistry","Physics","Mathematics","Computer Science","Statistics"]},{"name":"Social Sciences","topics":["Economics","Political Science","Sociology","Psychology","History","Geography"]}]},{"system_id":"baaea996-b2e0-4f23-87fd-d7ef3bce6301","level":"Sindh Universities Entry Test","subjects":[{"name":"Mathematics","topics":["Algebra","Calculus","Trigonometry","Statistics","Geometry","Matrices"]},{"name":"English & Aptitude","topics":["Grammar","Vocabulary","Comprehension","Analytical Reasoning","IQ","Logical Reasoning"]},{"name":"Science Subjects","topics":["Biology","Chemistry","Physics","Computer Science","Statistics","Environmental Science"]},{"name":"General Knowledge","topics":["Pakistan Studies","Sindh Studies","Current Affairs","Islamic Studies","World GK","Science GK"]}]}]'::jsonb)
    AS x(system_id uuid, level text, subjects jsonb)
),
ins_levels AS (
  INSERT INTO public.levels (system_id, name, order_index, approved, auto_created)
  SELECT p.system_id, p.level, 0, true, true FROM payload p
  WHERE NOT EXISTS (SELECT 1 FROM public.levels l WHERE l.system_id=p.system_id AND l.name=p.level)
  RETURNING id, system_id, name
),
all_levels AS (
  SELECT id, system_id, name FROM ins_levels
  UNION ALL
  SELECT l.id, l.system_id, l.name FROM public.levels l
    JOIN payload p ON p.system_id=l.system_id AND p.level=l.name
),
subj_rows AS (
  SELECT al.id AS level_id, (s->>'name') AS subj_name, (s->'topics') AS topics
  FROM payload p
  JOIN all_levels al ON al.system_id=p.system_id AND al.name=p.level
  CROSS JOIN LATERAL jsonb_array_elements(p.subjects) AS s
),
ins_subjects AS (
  INSERT INTO public.subjects (level_id, name, approved, auto_created)
  SELECT DISTINCT sr.level_id, sr.subj_name, true, true FROM subj_rows sr
  WHERE NOT EXISTS (SELECT 1 FROM public.subjects s WHERE s.level_id=sr.level_id AND s.name=sr.subj_name)
  RETURNING id, level_id, name
),
all_subjects AS (
  SELECT id, level_id, name FROM ins_subjects
  UNION ALL
  SELECT s.id, s.level_id, s.name FROM public.subjects s
    JOIN subj_rows sr ON sr.level_id=s.level_id AND sr.subj_name=s.name
),
topic_rows AS (
  SELECT DISTINCT asu.id AS subject_id, t.value AS topic_name
  FROM subj_rows sr
  JOIN all_subjects asu ON asu.level_id=sr.level_id AND asu.name=sr.subj_name
  CROSS JOIN LATERAL jsonb_array_elements_text(sr.topics) AS t
)
INSERT INTO public.topics (subject_id, name, approved, auto_created)
SELECT tr.subject_id, tr.topic_name, true, true FROM topic_rows tr
WHERE NOT EXISTS (SELECT 1 FROM public.topics tp WHERE tp.subject_id=tr.subject_id AND tp.name=tr.topic_name);